 auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};LibraryStore::root().createDirectory();juce::AudioFormatManager formats;formats.registerBasicFormats();auto began=juce::Time::getMillisecondCounterHiRes();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(juce::File(input)));require(reader!=nullptr,"benchmark source available");int count=(int)juce::jmin(reader->lengthInSamples,(juce::int64)(reader->sampleRate*240));require(count>=reader->sampleRate*240,"four minute source required");auto audio=std::make_shared<juce::AudioBuffer<float>>(2,count);require(reader->read(audio.get(),0,count,0,true,true),"decode four minutes");double decode=juce::Time::getMillisecondCounterHiRes()-began;TrackStemWorker worker;auto started=juce::Time::getMillisecondCounterHiRes();worker.setSource(audio,reader->sampleRate,true,false,0,false,true);double first=-1;auto deadline=started+240000;while(juce::Time::getMillisecondCounterHiRes()<deadline){auto now=juce::Time::getMillisecondCounterHiRes();auto w=worker.result();if(first<0&&w&&w->covers(0,44100*.1)){first=now-started;std::cout<<"First stem region "<<first<<" ms\n"<<std::flush;}if(worker.complete)break;if(worker.status==3)throw std::runtime_error(worker.errorText().toStdString());juce::Thread::sleep(10);}require(worker.complete,"whole four minute track prepared");double full=juce::Time::getMillisecondCounterHiRes()-started;auto window=worker.result();require(window&&window->covers(0,44100LL*240),"complete contiguous stems retained");for(int second:{0,30,90,180,239}){std::array<float,4> values{};require(window->read(second*44100.+100,0,values),"arbitrary jump immediately readable after preparation");for(float v:values)require(std::isfinite(v),"finite cached stems");}
